import type { Metadata } from 'next'
import { LandingHeader } from '@/components/landing/landing-header'
import { SurveyForm } from '@/components/landing/survey-form'

export const metadata: Metadata = {
  title: 'Nestni Market Survey',
  description: 'Help us understand your property management needs and build a better Nestni experience.',
}

export default function SurveyPage() {
  return (
    <main id="top" className="min-h-screen bg-[#e6f7f4] text-[#111111]">
      <LandingHeader />
      <section className="mx-auto max-w-4xl px-5 py-10 sm:px-8 sm:py-14 lg:px-10" aria-labelledby="survey-heading">
        <header className="mb-8 max-w-3xl">
          <p className="text-sm font-bold uppercase tracking-[0.16em] text-[#007d6c]">Nestni market survey</p>
          <h1 id="survey-heading" className="mt-3 text-3xl font-semibold leading-tight tracking-[-0.04em] text-[#183147] sm:text-4xl">
            Help us understand your property management needs.
          </h1>
          <p className="mt-4 text-base leading-7 text-[#4b5563] sm:text-lg">
            Your feedback will help us build a better Nestni experience for owners and tenants.
          </p>
        </header>
        <div className="rounded-2xl border border-[#e5e7eb] bg-white p-5 shadow-sm sm:p-8 lg:p-10">
          <SurveyForm />
        </div>
      </section>
    </main>
  )
}
